const TZ = 'Asia/Ho_Chi_Minh';
// The NocoDB node nests a row as { id, id_fields, fields }.
const rowsOf = (name) => ($(name).isExecuted ? $(name).all() : [])
  .map((i) => i.json || {})
  .filter((j) => j.id !== undefined && j.id !== null)
  .map((j) => ({ Id: j.id, ...(j.fields || {}) }));
const settingsOf = (name) => Object.fromEntries(
  rowsOf(name).filter((r) => r.key).map((r) => [r.key, (r.value ?? '').toString().trim()]));
const linesOf = (v) => String(v || '').split('\n').map((s) => s.trim()).filter(Boolean);
// NocoDB returns DateTime in UTC as "2026-09-17 13:00:00+00:00".
const parseDt = (s) => DateTime.fromISO(String(s || '').trim().replace(' ', 'T'), { setZone: true }).setZone(TZ);
const iso = (dt) => dt.setZone(TZ).toISO({ suppressMilliseconds: true });

// Every chat-agent tool except write_post: reads answer here, writes are returned as `writes`
// for the NocoDB nodes after this one. The guards live here, not in the prompt.
const a = $('When called').first().json;
const now = DateTime.now().setZone(TZ);
const str = (v) => (v === undefined || v === null ? '' : String(v)).trim();
const int = (v, d, lo, hi) => { const n = Number(v); return Number.isInteger(n) && n >= lo && n <= hi ? n : d; };
const cut = (s, n) => { s = str(s); return s.length > n ? `${s.slice(0, n)}…` : s; };
const when = (s) => (s ? parseDt(s).toFormat('dd/MM HH:mm') : null);
const settingsRows = rowsOf('Settings');
const settings = settingsOf('Settings');
const ideas = rowsOf('Ideas');
const posts = rowsOf('Posts');
const outcomes = rowsOf('Outcomes');
const done = (result, writes = []) => [{ json: { result, writes } }];
const refuse = (why) => done({ ok: false, refused: why });
const ideaOut = (i) => ({ idea_id: i.Id, theme: i.theme, hook: i.hook || null, angle: i.angle || null, source: i.source, source_url: i.source_url || null, owner_words: i.owner_words || null, note: i.note || null, picture: i.picture || null, banked_at: when(i.banked_at), used: Boolean(i.used) });
const postOut = (p) => ({ post_id: p.Id, idea_id: p.idea_id, content_type: p.content_type, status: p.status, scheduled_for: when(p.scheduled_for), published_at: when(p.published_at), preview: cut(p.text, 200) });
const settingsOut = (s) => ({ slots: linesOf(s.slots), daily_quota: Number(s.daily_quota) || 0, topics: linesOf(s.topics), avoid: linesOf(s.avoid), rules: linesOf(s.rules), next_offer: s.next_offer || null });
const norm = (s) => str(s).toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g, '').replace(/đ/g, 'd').replace(/[^a-z0-9 ]/g, ' ').replace(/\s+/g, ' ').trim();
const distance = (x, y) => {
  const d = Array.from({ length: y.length + 1 }, (_, j) => j);
  for (let i = 1; i <= x.length; i++) {
    let prev = d[0]; d[0] = i;
    for (let j = 1; j <= y.length; j++) { const t = d[j]; d[j] = Math.min(d[j] + 1, d[j - 1] + 1, prev + (x[i - 1] === y[j - 1] ? 0 : 1)); prev = t; }
  }
  return d[y.length];
};

switch (a.tool) {
  case 'read_ideas': {
    const q = norm(a.q);
    const rows = ideas
      .filter((i) => (a.include_used === true || a.include_used === 'true' || !i.used) && (!q || norm(`${i.theme} ${i.hook}`).includes(q)))
      .sort((x, y) => y.Id - x.Id)
      .slice(0, int(a.limit, 10, 1, 30))
      .map((i) => ({ idea_id: i.Id, theme: cut(i.theme, 200), hook: cut(i.hook, 200) || null, source: i.source, banked_at: when(i.banked_at), used: Boolean(i.used) }));
    return done({ ok: true, rows, unused_in_bank: ideas.filter((i) => !i.used).length });
  }
  case 'bank_idea': {
    const fields = {};
    for (const [k, n] of [['theme', 120], ['hook', 500], ['angle', 500], ['source_url', 500], ['owner_words', 4000], ['note', 500], ['picture', 200]]) {
      if (str(a[k])) fields[k] = str(a[k]).slice(0, n);
    }
    if (fields.picture && !/^\S+ \S+$/.test(fields.picture)) return refuse('picture phải là mã tham chiếu của ảnh, y như trong danh sách ảnh: <message id> <image key>');
    const id = Number(a.idea_id) || 0;
    if (id) {
      const row = ideas.find((i) => i.Id === id);
      if (!row) return refuse(`hong có ý tưởng #${id}`);
      if (!Object.keys(fields).length) return refuse('hong có trường nào để sửa');
      const merged = { ...row, ...fields };
      const keep = Object.fromEntries(['theme', 'hook', 'angle', 'source_url', 'owner_words', 'note', 'picture'].map((k) => [k, merged[k] ?? null]));
      return done({ ok: true, action: 'updated', row: ideaOut(merged) }, [{ table: 'ideas', op: 'update', _id: id, ...keep }]);
    }
    if (!fields.theme) return refuse('ý tưởng mới cần theme');
    const n = norm(fields.theme);
    const twin = ideas.find((i) => !i.used && norm(i.theme) && distance(norm(i.theme), n) <= Math.max(3, Math.floor(n.length * 0.2)));
    if (twin) return refuse(`trong kho đã có ý gần y vậy, chưa dùng: #${twin.Id} "${twin.theme}". Muốn sửa nó thì gọi lại với idea_id ${twin.Id}.`);
    const blank = Object.fromEntries(['hook', 'angle', 'source_url', 'owner_words', 'note', 'picture'].map((k) => [k, null]));
    return done({ ok: true, action: 'created' }, [{ table: 'ideas', op: 'create', ...blank, ...fields, source: 'owner', used: false, banked_at: iso(now) }]);
  }
  case 'read_posts': {
    const id = Number(a.post_id) || 0;
    if (id) {
      const p = posts.find((x) => x.Id === id);
      if (!p) return refuse(`hong có bài #${id}`);
      return done({ ok: true, row: { ...postOut(p), text: p.text || '', leads_to_offer: p.leads_to_offer || null, check_result: p.check_result ? JSON.parse(p.check_result) : null, issues: p.issues || null, fb_post_id: p.fb_post_id || null } });
    }
    const rows = posts.filter((p) => !str(a.status) || p.status === str(a.status))
      .sort((x, y) => y.Id - x.Id).slice(0, int(a.limit, 10, 1, 20)).map(postOut);
    const count = (s) => posts.filter((p) => p.status === s).length;
    return done({ ok: true, rows, counts: { needs_owner: count('needs_owner'), approved: count('approved'), writing: count('writing') } });
  }
  case 'update_post': {
    const id = Number(a.post_id) || 0;
    const p = posts.find((x) => x.Id === id);
    if (!p) return refuse(`hong có bài #${id}`);
    if (p.fb_post_id || ['publishing', 'published'].includes(p.status)) return refuse(`bài #${id} đã lên Facebook (hoặc đang lên), hong sửa ở đây được`);
    if (p.status === 'writing') return refuse(`bài #${id} còn đang viết; đợi thẻ tới rồi hãy sửa`);
    const fields = {};
    const text = str(a.text);
    if (text) {
      if (text.length > 3000) return refuse('bài dài quá 3000 ký tự');
      fields.text = text;
      fields.owner_edited = true;
      // The owner changed an approved post themselves: the approval follows their text (G6).
      if (p.status === 'approved') fields.approved_text = text;
    }
    if (str(a.scheduled_for)) {
      const at = DateTime.fromISO(str(a.scheduled_for), { zone: TZ });
      if (!at.isValid) return refuse(`giờ đăng "${a.scheduled_for}" hong đọc được; gửi dạng 2026-09-27T20:00`);
      if (at <= now) return refuse('giờ đăng phải ở tương lai');
      fields.scheduled_for = iso(at);
    }
    if (!Object.keys(fields).length) return refuse('hong có gì để sửa: gửi text hoặc scheduled_for');
    const keep = { text: p.text, owner_edited: Boolean(p.owner_edited), approved_text: p.approved_text ?? null, scheduled_for: p.scheduled_for ? iso(parseDt(p.scheduled_for)) : null };
    return done({ ok: true, row: { post_id: id, status: p.status, text: fields.text || p.text, scheduled_for: when(fields.scheduled_for || p.scheduled_for) } }, [{ table: 'posts', op: 'update', _id: id, ...keep, ...fields }]);
  }
  case 'read_outcomes': {
    const id = Number(a.post_id) || 0;
    const since = now.minus({ days: int(a.since_days, 14, 1, 90) });
    const rows = posts
      .filter((p) => p.published_at && (id ? p.Id === id : parseDt(p.published_at) >= since))
      .sort((x, y) => String(y.published_at).localeCompare(String(x.published_at)))
      .slice(0, int(a.limit, 10, 1, 20))
      .map((p) => ({
        post_id: p.Id, content_type: p.content_type, published_at: when(p.published_at), slot: p.slot || null, preview: cut(p.text, 120),
        checkpoints: Object.fromEntries(outcomes.filter((o) => o.post_id === p.Id).map((o) => [o.checkpoint, { reach: o.reach, reactions: o.reactions, comments: o.comments, shares: o.shares }])),
      }));
    return done({ ok: true, rows, note: 'reach = số người xem; số này nói bài đi xa tới đâu, hong nói bài bán được hàng hay hong' });
  }
  case 'read_settings':
    return done({ ok: true, row: settingsOut(settings) });
  case 'update_settings': {
    const next = {};
    if (str(a.slots)) {
      const slots = linesOf(str(a.slots).replace(/,/g, '\n')).map((s) => s.toLowerCase());
      const bad = slots.filter((s) => !/^(mon|tue|wed|thu|fri|sat|sun)-([01]\d|2[0-3]):[0-5]\d$/.test(s));
      if (bad.length) return refuse(`khung giờ sai dạng: ${bad.join(', ')}. Dạng đúng: sat-20:00`);
      if (!slots.length || slots.length > 14) return refuse('cần từ 1 tới 14 khung giờ');
      next.slots = [...new Set(slots)].join('\n');
    }
    if (str(a.daily_quota)) {
      const q = Number(a.daily_quota);
      if (!Number.isInteger(q) || q < 0 || q > 5) return refuse('daily_quota phải là số nguyên từ 0 tới 5');
      next.daily_quota = String(q);
    }
    for (const k of ['topics', 'avoid', 'rules']) {
      if (!str(a[k])) continue;
      const list = linesOf(str(a[k]));
      if (list.length > 20) return refuse(`${k} tối đa 20 dòng`);
      next[k] = list.join('\n');
    }
    if (!Object.keys(next).length) return refuse('hong có gì để đổi');
    const writes = [];
    for (const [key, value] of Object.entries(next)) {
      const row = settingsRows.find((r) => r.key === key);
      if (!row) return refuse(`bảng settings thiếu dòng ${key}`);
      writes.push({ table: 'settings', op: 'update', _id: row.Id, value });
    }
    return done({ ok: true, before: settingsOut(settings), after: settingsOut({ ...settings, ...next }) }, writes);
  }
  default:
    return refuse(`không có công cụ "${a.tool}"`);
}

// Reached once, after the writes or straight from Plan when there were none.
const r = { ...$('Plan').first().json.result };
if ($('Create idea').isExecuted) {
  const c = $('Create idea').first().json;
  const id = c.id ?? c.Id ?? (c.fields || {}).Id;
  const w = $('Plan').first().json.writes[0];
  r.row = { idea_id: id, theme: w.theme, hook: w.hook || null, angle: w.angle || null, source: 'owner', owner_words: w.owner_words || null, picture: w.picture || null };
}
return [{ json: r }];
